class Permissions:
    def __init__(self): 
        self.roles = {"viewer": {"read"}, "editor": {"read", "write"}}
        self.inheritance = {}

    def define_role(self, name, actions, inherits=None):
        self.roles[name] = set(actions)
        self.inheritance[name] = inherits

    def allowed(self, role, action): 
        permissions = self.roles.get(role, set())
        if self.inheritance.get(role):
            for inherited_role in self.inheritance[role]:
                permissions.update(self.allowed(inherited_role, action))
        return action in permissions 
